def plugin_metadata() -> dict[str, Any]:
    root = _find_plugin_root()
    if root is None:
        raise ValueError("Elyra plugin.json not found; run the packaged runtime without moving its files")
    manifest = json.loads((root / "plugin.json").read_text(encoding="utf-8"))
    if manifest.get("id") != "elyra.ngs-analysis" or not manifest.get("version"):
        raise ValueError("NGS package identity missing; reinstall the verified Elyra package")
    return {"id": manifest["id"], "name": manifest["name"], "version": manifest["version"], "package_digest": manifest.get("integrity", {}).get("digest"), "source_root": str(root)}

