def salmon_libtype(layout: str, strandedness: str) -> tuple[str, str]:
    normalized = strandedness.lower().strip()
    if layout not in {"PE", "SE"}:
        raise ValueError("Specify PE or SE from the supplied reads before selecting a Salmon library type")
    if normalized not in {"forward", "reverse", "unstranded", "auto"}:
        raise ValueError("Strandedness is not specified: provide forward, reverse or unstranded from library preparation evidence, or explicitly choose auto for Salmon inference")
    if normalized == "auto":
        return "A", "explicit_salmon_inference"
    library_types = {"PE": {"forward": "ISF", "reverse": "ISR", "unstranded": "IU"},
                     "SE": {"forward": "SF", "reverse": "SR", "unstranded": "U"}}
    return library_types[layout][normalized], "from_input"

